testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { montarRespostaDeErro } from './solution.mjs';

test('erro conhecido com status 404 mantém status e mensagem', () => {
  assert.deepEqual(montarRespostaDeErro({ status: 404, mensagem: 'livro não encontrado' }), {
    status: 404,
    corpo: { erro: { mensagem: 'livro não encontrado' } },
  });
});

test('erro de validação (400) também passa com a mensagem', () => {
  const resposta = montarRespostaDeErro({ status: 400, mensagem: 'preco inválido' });
  assert.equal(resposta.status, 400);
  assert.equal(resposta.corpo.erro.mensagem, 'preco inválido');
});

test('erro inesperado vira 500 com mensagem genérica e sem detalhes', () => {
  const resposta = montarRespostaDeErro(new Error('conexão com o banco caiu'));
  assert.equal(resposta.status, 500);
  assert.equal(resposta.corpo.erro.mensagem, 'erro interno do servidor');
  assert.equal(resposta.corpo.erro.stack, undefined);
});

test('detalhes: true mostra a mensagem original; status fora de 400..599 vira 500', () => {
  const detalhado = montarRespostaDeErro(new Error('conexão caiu'), { detalhes: true });
  assert.equal(detalhado.corpo.erro.mensagem, 'conexão caiu');

  const estranho = montarRespostaDeErro({ status: 700, mensagem: 'isso não existe' });
  assert.equal(estranho.status, 500);
  assert.equal(estranho.corpo.erro.mensagem, 'erro interno do servidor');
});

solutionCode:
export function montarRespostaDeErro(erro, opcoes) {
  const status =
    Number.isInteger(erro?.status) && erro.status >= 400 && erro.status <= 599
      ? erro.status
      : 500;

  let mensagem;
  if (status < 500) {
    mensagem = erro?.mensagem ?? erro?.message ?? 'erro desconhecido';
  } else if (opcoes?.detalhes === true) {
    mensagem = erro?.mensagem ?? erro?.message ?? 'erro interno do servidor';
  } else {
    mensagem = 'erro interno do servidor';
  }

  return { status, corpo: { erro: { mensagem } } };
}
